output_schema:
{
  "node_text": "String (Setup sentence + choice prompt. Max 2 sentences)",
  "visual_style": "String",
  "character_anchor": "String (Max 15 words)",
  "visual_context": "String (Max 20 words)",
  "choices": [
    { "choice_text": "Positive action", "behavior_type": "Positive" },
    { "choice_text": "Negative action", "behavior_type": "Negative" }
  ]
}

examples:
Example 1 (Age 7, Sharing):
{
  "node_text": "{{Child_Name}}'s friend wants to play with their toy. Should {{Child_Name}} share?",
  "visual_style": "Pixar 3D style, bright colors, rounded shapes, warm lighting",
  "character_anchor": "Green dinosaur, blue cap, friendly expression",
  "visual_context": "Pixar style, green dinosaur with blue cap, friend asking for toy, sunny room, warm lighting",
  "choices": [
    { "choice_text": "Share the toy", "behavior_type": "Positive" },
    { "choice_text": "Say no", "behavior_type": "Negative" }
  ]
}

Example 2 (Age 11, Patience):
{
  "node_text": "{{Child_Name}} is waiting in line. Their turn is coming soon.",
  "visual_style": "Digital art, cel-shaded, vibrant, slightly detailed",
  "character_anchor": "Blue astronaut, orange suit, confident pose",
  "visual_context": "Digital art, blue astronaut in orange suit, standing in queue, others nearby, calm setting",
  "choices": [
    { "choice_text": "Wait patiently", "behavior_type": "Positive" },
    { "choice_text": "Push to the front", "behavior_type": "Negative" }
  ]
}
